<script setup lang="ts">
definePageMeta({middleware:['auth','repairer']})
const supabase=useSupabaseClient(); const {company,loadProfile}=useProfile(); const rows=ref<any[]>([]); const loading=ref(true)
onMounted(async()=>{await loadProfile(); if(!isValidUuid(company.value?.id)){loading.value=false;return} const {data}=await supabase.from('wanted_requests').select('*, vehicles(*), wanted_offers(id,status)').eq('repairer_company_id',company.value.id).order('created_at',{ascending:false}); rows.value=data||[]; loading.value=false})
</script>
<template><section class="section"><div class="container"><div style="display:flex;justify-content:space-between;gap:16px;align-items:end;flex-wrap:wrap"><div><div class="kicker">Repairer portal</div><h1 class="page-title">Wanted Parts</h1></div><NuxtLink class="btn btn-primary" to="/repairer/wanted/new">Create Request</NuxtLink></div><div v-if="loading" class="card empty-state">Loading requests…</div><div v-else-if="!rows.length" class="card empty-state"><h2>No wanted requests</h2><p class="muted">Create your first request and suppliers can respond.</p></div><div v-else class="grid" style="gap:14px;margin-top:22px"><NuxtLink v-for="r in rows" :key="r.id" :to="`/repairer/wanted/${r.id}`" class="card" style="padding:20px"><div style="display:flex;justify-content:space-between;gap:15px"><div><h3 style="margin:0">{{r.part_name}}</h3><p class="muted" style="margin-bottom:0">{{r.delivery_city||'—'}} · {{r.delivery_state_region||''}}</p></div><div><span class="badge">{{r.status}}</span><p class="muted" style="text-align:right">{{r.wanted_offers?.length||0}} offers</p></div></div></NuxtLink></div></div></section></template>
